fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    if len == 0 {
        return Vec::new(); // This case should not happen as per the problem statement.
    }

    // Calculate effective rotation amount
    let effective_rotation = n % len;
    if effective_rotation == 0 {
        return list.clone(); // No rotation needed
    }

    // Calculate the split index
    let split_index = len - effective_rotation;

    // Create the new rotated array
    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[split_index..]); // Suffix
    new_list.extend_from_slice(&list[..split_index]); // Prefix

    new_list
}